[TFMpageType('OfflineManagement', "@TFM:OfflineManagement")]
class TFMPageOfflineManagementConfiguration extends TFMPageConfiguration
{
    TFMPageID		        navigateToButton;
    boolean                 postAllEnabled;
    TFMPageTitleString		postAllTitle;
    boolean                 refreshEnabled;
    TFMPageTitleString		refreshTitle;
    TFMOfflineUpdateMode	updateMode; //OnNoOrders, Manual, Always.

}

