[TFMPageConfigurationAttributeAttribute(TFMOfflineUpdateMode::Always,'','updateMode')]
public TFMOfflineUpdateModeEDT parmUpdateMode(TFMOfflineUpdateModeEDT _updateMode = updateMode)
{
    updateMode = _updateMode;
    return updateMode;
}

[TFMPageConfigurationAttributeAttribute('MainMenu','navigateToButton', 'navigateTo', true),TFMPageAction]
