/// <summary>
///
/// </summary>
/// <param name = "_parent"></param>
public Map appendToXML(XmlElement _parent, TFMPage _page)
{
    XmlElement offlineManagementConfiguration;
    XmlElement firstElement;
    SetEnumerator offlineServicesEnum;
    TFMPageOfflinePages offlinePages;
    TFMPageOfflineManagementServiceConfiguration offlineService;
    TFMPageOfflineManagementOrderServiceConfiguration offlineOrderService;
    XmlElement	servicesNode;
    Set offlineServices = new Set(Types::Class);

    super(_parent, _page);

    servicesNode = _parent.ownerDocument().createElement('offlineServices');

    while select offlinePages where offlinePages.PageID == 'OfflineManagementPage'
    {
        if(offlinePages.OfflinePageID == 'AdhocRegistrations') 
        {
            offlineService = new TFMPageOfflineManagementAdhocServiceConfiguration();
        } else
        {
            offlineOrderService = new TFMPageOfflineManagementOrderServiceConfiguration();
            offlineOrderService.parmServiceId(offlinePages.OfflinePageID);
            offlineService = offlineOrderService;
        }

        offlineService.parmListId(offlinePages.ListID);
        offlineService.parmOnItemSelectedNavigateTo(offlinePages.OfflinePageID);
        offlineServices.add(offlineService);
    }

    offlineServicesEnum = offlineServices.getEnumerator();
    while(offlineServicesEnum.moveNext())
    {
        offlineService = offlineServicesEnum.current() as TFMPageOfflineManagementServiceConfiguration;
        offlineService.appendToXML(servicesNode);
    }

    offlineManagementConfiguration = _parent.getNamedElement('offlineManagementConfiguration');
    firstElement = offlineManagementConfiguration.firstChild();
    if(firstElement)
    {
        offlineManagementConfiguration.insertBefore(servicesNode, offlineManagementConfiguration.firstChild());
    }
    else
    {
        offlineManagementConfiguration.appendChild(servicesNode);
    }

    return new Map(Types::String, Types::Class);
}
